const norm = (s: string) => s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9].*$/, "");

/** frame of the nth occurrence of a word (0-based), from its real start time */
export const at = (word: string, nth = 0): number => {
  const hits = WORDS.filter((x) => norm(x.w) === norm(word));
  return Math.round((hits[Math.min(nth, hits.length - 1)]?.s ?? 0) * 30);
};

/** seconds of the nth occurrence of a word */
export const sec = (word: string, nth = 0): number => {
  const hits = WORDS.filter((x) => norm(x.w) === norm(word));
  return hits[Math.min(nth, hits.length - 1)]?.s ?? 0;
};
